Flux<TelemetrySample> samples = Flux.fromIterable(request.samples()).map(s -> new TelemetrySample(request.deviceId(), s.metric(), s.tDevice(), Instant.EPOCH, s.value(), ValidationStatus.VALIDATED, s.payload()));
return useCase.ingest(principal.getName(), samples).map(summary -> summary.refused()
        ? ResponseEntity.<IngressPacketResponse>status(HttpStatus.FORBIDDEN).build()
        : ResponseEntity.accepted().body(new IngressPacketResponse(summary.appended(), summary.rejectedValidation(), summary.revisions(), summary.duplicates())));
